import React from "react";
import StatCard from "./StatCard";
import RevenueChart from "./RevenueChart";

interface Stat {
  label: string;
  value: string;
  change: number;
  trend: "up" | "down" | "neutral";
}

interface MockData {
  revenue: number[];
  users: number[];
  orders: number[];
  churn: number[];
}

const mockData: MockData = {
  revenue: [12000, 13500, 14200, 15000, 16800, 17500, 18900, 19500, 20500, 21200, 22000, 23000],
  users: [1200, 1350, 1420, 1500, 1680, 1750, 1890, 1950, 2050, 2120, 2200, 2300],
  orders: [850, 920, 980, 1050, 1180, 1250, 1390, 1450, 1550, 1620, 1700, 1800],
  churn: [5.2, 4.8, 4.5, 4.3, 4.1, 4.0, 3.9, 3.8, 3.7, 3.6, 3.5, 3.4],
};

const stats: Stat[] = [
  {
    label: "Revenue",
    value: "$23,000",
    change: 15,
    trend: "up",
  },
  {
    label: "Users",
    value: "2,300",
    change: 8,
    trend: "up",
  },
  {
    label: "Orders",
    value: "1,800",
    change: 5,
    trend: "up",
  },
  {
    label: "Churn",
    value: "3.4%",
    change: -2,
    trend: "down",
  },
];

export const App: React.FC = () => {
  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-900 mb-8">Dashboard</h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {stats.map((stat) => (
            <StatCard key={stat.label} stat={stat} />
          ))}
        </div>

        <div className="bg-white rounded-lg shadow-sm border p-6">
          <h2 className="text-2xl font-semibold text-gray-900 mb-6">Monthly Revenue</h2>
          <RevenueChart data={mockData.revenue} />
        </div>
      </div>
    </div>
  );
};
