### RevenueChart.tsx
```tsx
import React from "react";
import { Line } from "recharts";
import { TrendingUpIcon, TrendingDownIcon } from "lucide-react";

interface RevenueChartProps {
  data: number[];
}

const RevenueChart: React.FC<RevenueChartProps> = ({ data }) => {
  const chartData = data.map((value, index) => ({
    name: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][index],
    revenue: value,
  }));

  return (
    <div className="h-64 flex items-end justify-between mt-4">
      <Line
        data={chartData}
        type="monotone"
        margin={{ top: 10, right: 30, left: 0, bottom: 10 }}
        stroke="#047857"
        strokeWidth={3}
        dot={false}
        activeDot={{ r: 8 }}
        className="stroke-accent"
      />
      <div className="absolute bottom-4 right-4 text-sm text-gray-600">
        Revenue (in $)
      </div>
    </div>
  );
};

export default RevenueChart;
```

### StatCard.tsx
```tsx
import React from "react";
import { TrendingUpIcon, TrendingDownIcon } from "lucide-react";

interface StatCardProps {
  stat: {
    label: string;
    value: string;
    change: number;
    trend: "up" | "down" | "neutral";
  };
}

const StatCard: React.FC<StatCardProps> = ({ stat }) => {
  const getArrowIcon = () => {
    if (stat.trend === "up") {
      return <TrendingUpIcon className="w-4 h-4 text-green-500" />;
    } else if (stat.trend === "down") {
      return <TrendingDownIcon className="w-4 h-4 text-red-500" />;
    } else {
      return <TrendingUpIcon className="w-4 h-4 text-gray-400" />;
    }
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100 hover:shadow-md transition-shadow duration-200">
      <h3 className="text-sm font-medium text-gray-500">{stat.label}</h3>
      <div className="mt-2 flex items-end justify-between">
        <div className="text-2xl font-bold text-gray-900">{stat.value}</div>
        <div className="flex items-center mt-1">
          {getArrowIcon()}
          <span className={`ml-1 text-sm ${stat.change >= 0 ? 'text-green-500' : 'text-red-500'}`}>
            {stat.change > 0 ? '+' : ''}{stat.change}%
          </span>
        </div>
      </div>
    </div>
  );
};

export default StatCard;
```
